head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > showChooseOption]<br/>Body Column 정보를 사용하여 특정 Column 에 chooseOption 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 chooseOption 속성을 설정할 Body Column 의 ID 를 설정할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (gdl_boolean 등)
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 테스트 참고 라벨 (grid 생성 전에 먼저 생성)
    $c.gcm.createLabel('label="[전제] 컬럼 사번(emp·text) / 부서(dept·text) / 등급(grade·select) / 상태(status·select)\n[절차] columnInfo(ID)+chooseOption(true/false) 선택 후 showChooseOption 클릭\n[확인] 대상 select 편집 드롭다운의 아이템 수/첫 아이템 라벨 (true=선택 안내 추가, false=제거). 등급은 chooseOptionLabel(== 등급 선택 ==), 상태는 기본값. text 컬럼(사번)은 미동작"', '', 'label1');

    // 바인딩 DataList 생성 (grade/status 는 select value 와 매칭)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="emp" name="emp" dataType="text"></w2:column>';
    strDl += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDl += '<w2:column id="grade" name="grade" dataType="text"></w2:column>';
    strDl += '<w2:column id="status" name="status" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    let rows = [
        ['1001', '영업팀', 'E1', 'S1'],
        ['1002', '개발팀', 'E2', 'S1'],
        ['1003', '인사팀', 'E3', 'S2'],
        ['1004', '재무팀', 'E4', 'S3']
    ];
    for (let r = 0; r < rows.length; r++) {
        strDl += '<w2:row>';
        strDl += '<emp><![CDATA[' + rows[r][0] + ']]></emp>';
        strDl += '<dept><![CDATA[' + rows[r][1] + ']]></dept>';
        strDl += '<grade><![CDATA[' + rows[r][2] + ']]></grade>';
        strDl += '<status><![CDATA[' + rows[r][3] + ']]></status>';
        strDl += '</w2:row>';
    }
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);

    // target 생성 (Body inputType : text / text / select / select)
    let grp_comp = $c.gcm.getTestGroup('');
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:520px;height:230px;">';
    strTarget += '<w2:caption style="" id="caption1" value="사원 목록"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="100" inputType="text" id="hemp" value="사번"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="hdept" value="부서"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="hgrade" value="등급"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hstatus" value="상태"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="100" inputType="text" dataType="text" id="emp" dataList="emp"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" dataType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="140" inputType="select" dataType="text" id="grade" dataList="grade" chooseOptionLabel="== 등급 선택 ==">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:item><w2:label>사원</w2:label><w2:value>E1</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>대리</w2:label><w2:value>E2</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>과장</w2:label><w2:value>E3</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>부장</w2:label><w2:value>E4</w2:value></w2:item>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:column>';
    strTarget += '<w2:column width="*" inputType="select" dataType="text" id="status" dataList="status">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:item><w2:label>재직</w2:label><w2:value>S1</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>휴직</w2:label><w2:value>S2</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>퇴직</w2:label><w2:value>S3</w2:value></w2:item>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// showChooseOption(columnInfo, chooseOption) 실행 후 대상 select 컬럼의 편집 드롭다운 아이템 목록으로 검증
scwin.btn_showChooseOption_onclick = function () {
    let colVal = par_columnInfo.getValue();                 // columnInfo : ID
    let flag = (par_chooseOption.getText() === 'true');    // chooseOption : true/false (gdl_boolean 은 getText 로 라벨 조회, getValue 는 값 2/3)

    let cellInfo = target1.getCellInfo(colVal);
    let inputType = cellInfo && cellInfo.options ? cellInfo.options.inputType : '';

    // 편집중인 셀 정리
    target1.endEdit();

    // inputType 이 select 가 아닌 경우 : 동작하지 않음 (선택 안내 아이템 변화 없음)
    if (inputType !== 'select') {
        target1.showChooseOption(colVal, flag);
        wf_body_bottom.getObj("scwin").setReturnValue("showChooseOption('" + colVal + "', " + flag + ") : 대상 컬럼 inputType=" + inputType + " 이므로 미동작 (선택 안내 아이템 변화 없음)");
        return;
    }

    // select 컬럼 : 편집모드로 진입시켜 실제 select 인스턴스를 생성한 뒤 showChooseOption 을 적용하고 아이템 목록 확인
    let colIdx = target1.getColumnIndex(colVal);
    let gridId = target1.id;
    let td = document.querySelector("td[id*='" + gridId + "_cell_0_" + colIdx + "']");
    target1.setEditMode(td);

    setTimeout(function () {
        // 활성화된 select 에 chooseOption 적용 (true=추가 / false=제거)
        target1.showChooseOption(colVal, flag);

        let sel = target1.getCellInfo(colVal).select;
        let cnt = sel ? sel.itemArr.length : 0;
        let firstLabel = (sel && sel.itemArr[0]) ? sel.itemArr[0].label : '(없음)';

        wf_body_bottom.getObj("scwin").setReturnValue("showChooseOption('" + colVal + "', " + flag + ") : 편집모드 드롭다운 아이템 수=" + cnt + ", 첫 아이템 라벨='" + firstLabel + "'");

        // 편집모드 유지 : 선택 안내 아이템이 드롭다운에 표시된 상태로 둔다 (endEdit 호출하지 않음)
    }, 200);
}
